for (const e of ENCYCLO) if (!e.game) e.game = e.id;
export const BY_ID = Object.fromEntries(ENCYCLO.map(e => [e.id, e]));
export const isEdible = e => e.cat === 'c';
export const isDanger = e => e.cat === 't' || e.cat === 'm';

// Points et badges du quiz (utilisés par game.js)
export function quizStats(me) {
  const q = (me && me.quiz) || {}, m = q.m || {};
  const mast = Object.keys(m).filter(k => m[k] >= MASTER_N && BY_ID[k]);
  const deadly = ENCYCLO.filter(e => e.cat === 'm');
  return { mastered: mast.length, deadlyAll: deadly.every(e => (m[e.id] || 0) >= MASTER_N), weeks: (q.w || []).length };
}
